(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9408],{22205:function(a,e,i){Promise.resolve().then(i.bind(i,47823))},47823:function(a,e,i){"use strict";i.r(e),i.d(e,{default:function(){return s}});var r=i(3827);i(64090);var n=i(31725);let t={updatedAt:"2026-06-16",articleHeadline:"Hepsiburada K\xe2r Hesaplama: Komisyon, İşlem Bedeli, KDV ve Stopaj Dahil Net K\xe2r Rehberi",articleDescription:"Hepsiburada satıcıları i\xe7in komisyon, kargo, platform hizmet bedeli + işlem bedeli, KDV ve stopaj dahil net k\xe2r hesaplama rehberi; g\xfcncel oranlar ve adım adım işlenmiş \xf6rnek.",blocks:[{type:"prose",heading:"Hepsiburada’da Net K\xe2r Nasıl Hesaplanır?",paragraphs:["Hepsiburada’da bir satıştan elinize kalan tutar, satış fiyatından komisyon, iki ayrı sabit platform \xfccreti, kargo, KDV ve stopaj d\xfcş\xfcld\xfckten sonra \xfcr\xfcn maliyetinin de \xe7ıkarılmasıyla bulunur. Hepsiburada’yı diğer pazaryerlerinden ayıran nokta, platform bedelini iki kalemde almasıdır: Platform Hizmet Bedeli ve İşlem Bedeli.","Bu iki sabit kalem, d\xfcş\xfck fiyatlı \xfcr\xfcnlerde marjı belirgin bi\xe7imde etkiler. Bu rehber, hangi kesintinin ne olduğunu, sabit \xfccretlerin toplamda ne kadar tuttuğunu ve net k\xe2rınızı en \xe7ok hangi kalemlerin aşındırdığını a\xe7ıklar."]},{type:"feeTable",heading:"Hepsiburada Kesinti Kalemleri (2026)",intro:"Hepsiburada iki ayrı sabit \xfccret alır; bunlar her sipariş i\xe7in değişmez. Komisyon ise kategoriye g\xf6re değişir.",columns:["Kalem","Oran / Tutar","A\xe7ıklama"],rows:[["Komisyon","Kategoriye g\xf6re %5 – %25","Satış tutarı \xfczerinden; kategoriye g\xf6re değişir, genelde Trendyol’a yakın."],["Komisyon KDV’si","%20 (sabit)","Hepsiburada komisyonu KDV-hari\xe7 belirtir, \xfczerine %20 KDV eklenir; bu komisyon KDV’si \xf6denecek KDV’nizden d\xfcş\xfcl\xfcr (indirilir)."],["Platform Hizmet Bedeli","2,50 + KDV = 3,00 TL","Her sipariş i\xe7in sabit kesinti."],["İşlem Bedeli","7,00 + KDV = 8,40 TL","Her sipariş i\xe7in sabit ikinci kesinti."],["Toplam sabit platform \xfccreti","11,40 TL (KDV dahil)","Platform Hizmet Bedeli + İşlem Bedeli. “Bug\xfcn kargoda” indirimi yoktur."],["Kargo","Desiye g\xf6re değişir","\xdcr\xfcn\xfcn desi/ağırlığına ve anlaşmalı kargo barem fiyatına g\xf6re."],["Satış KDV’si","\xdcr\xfcn\xfcn ger\xe7ek oranı","Satış fiyatına dahildir; \xfcr\xfcn\xfcn kendi KDV oranından hesaplanır."],["Stopaj","%1","KDV hari\xe7 satış tutarının %1’i; gelir vergisi peşin kesintisi."]],note:"Komisyon oranı kategoriye g\xf6re değişir; kesin oran i\xe7in yukarıdaki hesaplayıcıyı kullanın. Sabit 11,40 TL platform \xfccreti her siparişte uygulanır."},(0,i(77067).w)({platform:"hepsiburada",heading:"\xd6rnek: 299 TL’lik \xdcr\xfcnde Adım Adım Net K\xe2r",intro:"Aşağıdaki \xf6rnek %15 komisyon, 80 TL \xfcr\xfcn maliyeti ve 12 TL kargo varsayımıyladır. Platform hizmet bedeli, Hepsiburada’nın iki sabit \xfccretinin (2,50 + 7,00, KDV dahil 11,40 TL) toplamıdır.",salePrice:299,commissionRate:15,cost:80,cargoPrice:12,vatRate:20}),{type:"pitfalls",heading:"K\xe2rınızı Sessizce Yiyen Kalemler",intro:"Hepsiburada hesaplamasında en sık atlanan tuzaklar aşağıdadır.",items:[{title:"İki sabit \xfccreti tek sanmak",body:"Hepsiburada Platform Hizmet Bedeli (2,50) ve İşlem Bedeli (7,00) olmak \xfczere iki ayrı \xfccret alır. Sadece birini hesaba katmak kesintiyi eksik g\xf6sterir; toplam KDV dahil 11,40 TL’dir."},{title:"Komisyona KDV eklememek",body:"Komisyon tutarının \xfczerine ayrıca %20 KDV uygulanır. Yalnızca komisyon oranını d\xfcşmek ger\xe7ek kesintiyi olduğundan d\xfcş\xfck g\xf6sterir."},{title:"Sabit \xfccretin d\xfcş\xfck fiyatta etkisini g\xf6rmemek",body:"11,40 TL sabit \xfccret, 50 TL’lik bir \xfcr\xfcnde satışın beşte birinden fazlasıdır. D\xfcş\xfck fiyatlı \xfcr\xfcnlerde bu kalem marjı eritir."},{title:"Stopajı atlamak",body:"Her satıştan KDV hari\xe7 tutarın %1’i stopaj olarak kesilir; d\xfcş\xfck marjlı \xfcr\xfcnlerde net k\xe2rın hatırı sayılır kısmını alır."},{title:"İade kayıplarını g\xf6z ardı etmek",body:"İade edilen siparişlerde kargo ve operasyon maliyeti kalır. Y\xfcksek iade oranlı kategorilerde ger\xe7ek k\xe2rınız hesapladığınızdan d\xfcş\xfckt\xfcr."}]},{type:"prose",heading:"Sabit \xdccretler, KDV ve Stopajın Teknik Detayı",paragraphs:["Hepsiburada’nın iki sabit \xfccreti hizmet bedeli niteliğindedir, bu y\xfczden her ikisine de %20 KDV uygulanır: 2,50 + KDV = 3,00 TL ve 7,00 + KDV = 8,40 TL, toplam KDV dahil 11,40 TL. Bu tutar fiyattan bağımsız olarak her siparişte aynıdır; “bug\xfcn kargoda” gibi bir indirim mekanizması yoktur.","KDV tarafında kritik ayrım şudur: satış KDV’si, maliyet KDV’si ve stopaj matrahı \xfcr\xfcn\xfcn ger\xe7ek KDV oranından (\xf6rn. %1, %10, %20) hesaplanır; komisyon, kargo ve platform \xfccretlerinin KDV’si ise her zaman sabit %20’dir. \xd6denecek KDV, satış KDV’nizden bu gider KDV’lerinin d\xfcş\xfclmesiyle bulunur.","Stopaj, KDV hari\xe7 satış tutarının %1’idir: 299 TL’lik bir satışta (KDV %20 ise) stopaj = 299 / 1,20 \xd7 0,01 ≈ 2,49 TL olur ve yıl sonunda gelir vergisi beyannamenizde mahsup edilir."]},{type:"comparison",heading:"Hepsiburada’yı Diğer Pazaryerleriyle Karşılaştırın",intro:"Aynı \xfcr\xfcn\xfc farklı pazaryerlerinde satıyorsanız kesinti yapısı değişir. Her platformun k\xe2r hesaplayıcısıyla net k\xe2rınızı ayrı g\xf6r\xfcn.",rows:[{platform:"Trendyol",note:"Tek bir platform hizmet bedeli kesilir (5,99 veya 13,19 TL); “bug\xfcn kargoda” indirimi vardır.",href:"/trendyol-kar-hesaplama"},{platform:"N11",note:"Sabit \xfccret yerine y\xfczde bazlı pazarlama + pazaryeri hizmet bedeli kesilir.",href:"/n11-kar-hesaplama"},{platform:"Amazon",note:"Ayrı platform hizmet bedeli yoktur; ana kesinti referral komisyonudur.",href:"/amazon-turkiye-kar-hesaplama"}]}]},l={platform:"hepsiburada",name:"Hepsiburada",slug:"hepsiburada-kar-hesaplama",color:"#ff6000",heroSubtitle:"Komisyon, kargo, platform hizmet bedeli, işlem bedeli, KDV ve stopaj dahil net k\xe2rınızı anında hesaplayın.",ctaText:"Hepsiburada mağazanızı bağlayın, sipariş ve finansal verilerinizi otomatik analiz edin.",formulaLines:(0,r.jsxs)(r.Fragment,{children:["Net K\xe2r = Satış Tutarı",(0,r.jsx)("br",{}),"\xa0\xa0- Komisyon (Satış \xd7 Komisyon Oranı)",(0,r.jsx)("br",{}),"\xa0\xa0- Kargo Maliyeti (Desi barem fiyatı)",(0,r.jsx)("br",{}),"\xa0\xa0- Platform Hizmet Bedeli (2,50 ₺ + KDV)",(0,r.jsx)("br",{}),"\xa0\xa0- İşlem Bedeli (7,00 ₺ + KDV)",(0,r.jsx)("br",{}),"\xa0\xa0- \xdcr\xfcn Maliyeti (Tedarik + Ambalaj)",(0,r.jsx)("br",{}),"\xa0\xa0- \xd6denecek KDV (Satış KDV - Gider KDV'leri)",(0,r.jsx)("br",{}),"\xa0\xa0- Stopaj (Satış / 1.20 \xd7 0.01)"]}),formulaNote:(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)("strong",{style:{color:"inherit"},children:"\xd6nemli:"})," Hepsiburada iki ayrı sabit \xfccret alır: Platform Hizmet Bedeli 2,50 ₺ + KDV ve İşlem Bedeli 7,00 ₺ + KDV (toplam 11,40 ₺ KDV dahil). Satış ve maliyet KDV'si \xfcr\xfcn\xfcn ger\xe7ek KDV oranı \xfczerinden, pazaryerinin kendi hizmet bedellerinin KDV'si ise %20 \xfczerinden hesaplanır."]}),faq:[{q:"Hepsiburada k\xe2r hesaplama nasıl yapılır?",a:"Hepsiburada'da k\xe2r hesaplamak i\xe7in satış fiyatından komisyon, kargo maliyeti, platform hizmet bedeli (2,50 ₺), işlem bedeli (7,00 ₺), \xfcr\xfcn maliyeti, KDV ve stopaj d\xfcş\xfclmelidir."},{q:"Hepsiburada platform hizmet bedeli ne kadar?",a:"Hepsiburada iki ayrı sabit \xfccret alır: Platform Hizmet Bedeli 2,50 ₺ + KDV ve İşlem Bedeli 7,00 ₺ + KDV. Toplamda KDV dahil 11,40 ₺ sabit kesinti uygulanır."},{q:"Hepsiburada komisyon oranları ne kadar?",a:"Hepsiburada komisyon oranları kategoriye g\xf6re %5 ile %25 arasında değişir. Genel olarak Trendyol ile benzer oranlara sahiptir. Kesin oranlar \xfcr\xfcn kategorinize bağlıdır."},{q:"Hepsiburada stopaj nedir?",a:"Stopaj, devletin satıcıdan peşin aldığı gelir vergisi avansıdır. Oranı KDV hari\xe7 satış tutarının %1'idir. Form\xfcl: Stopaj = Satış Tutarı / 1.20 \xd7 0.01."},{q:"Hepsiburada KDV hesaplaması nasıl yapılır?",a:"Satış ve maliyet KDV'si \xfcr\xfcn\xfcn ger\xe7ek KDV oranı \xfczerinden (\xf6r. %1, %10, %20), Hepsiburada'nın komisyon/kargo/hizmet bedeli KDV'si ise %20 \xfczerinden hesaplanır. \xd6denecek KDV = Satış KDV − Gider KDV'leri."},{q:"Hepsiburada ve Trendyol farkları neler?",a:"En b\xfcy\xfck fark platform hizmet bedeli yapısıdır. Trendyol tek bir PHB keserken (5,99 ₺ veya 13,19 ₺), Hepsiburada PHB (2,50 ₺) + İşlem Bedeli (7,00 ₺) = 11,40 ₺ sabit keser."},{q:"NİTRU Hepsiburada destekliyor mu?",a:"Evet! NİTRU, Hepsiburada dahil 6 pazaryerini destekler: Trendyol, Hepsiburada, Amazon, N11, \xc7i\xe7eksepeti ve Pazarama. T\xfcm platformlardaki mağazalarınızı tek panelden y\xf6netebilirsiniz."}],blogLinks:[{href:"/blog/eticaret-kdv-stopaj-rehberi",label:"KDV ve Stopaj Rehberi"},{href:"/blog",label:"T\xfcm Blog Yazıları"}],content:t};function s(){return(0,r.jsx)(n.Z,{config:l})}}},function(a){a.O(0,[6669,5250,2406,6095,3897,9778,9952,7774,6676,9419,581,6972,8214,7447,3138,2971,8069,1744],function(){return a(a.s=22205)}),_N_E=a.O()}]);